"""A parser for standard 5-field cron expressions.

The public surface is small:

    schedule = parse_cron("30 8 * * 1,3,5")
    schedule.describe()   # "At 08:30 on Monday, Wednesday, and Friday"
    schedule.minutes      # (30,)

Everything else is a helper, arranged top-down: the entry point comes first,
then field parsing, then the parsed result, then the small formatting utilities
that the description layer leans on.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Sequence

__all__ = ["CronSchedule", "CronField", "CronParseError", "parse_cron"]


# --------------------------------------------------------------------------- #
# Field definitions
# --------------------------------------------------------------------------- #


class CronParseError(ValueError):
    """Raised when a cron expression is malformed or out of range."""


@dataclass(frozen=True)
class CronField:
    """Static metadata describing one of the five cron fields."""

    name: str
    min_value: int
    max_value: int

    def contains(self, value: int) -> bool:
        return self.min_value <= value <= self.max_value

    def full_range(self) -> range:
        return range(self.min_value, self.max_value + 1)


MINUTE = CronField("minute", 0, 59)
HOUR = CronField("hour", 0, 23)
DAY_OF_MONTH = CronField("day of month", 1, 31)
MONTH = CronField("month", 1, 12)
DAY_OF_WEEK = CronField("day of week", 0, 6)

CRON_FIELDS: tuple[CronField, ...] = (MINUTE, HOUR, DAY_OF_MONTH, MONTH, DAY_OF_WEEK)

WEEKDAY_NAMES: tuple[str, ...] = (
    "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday",
)

MONTH_NAMES: tuple[str, ...] = (
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December",
)


# --------------------------------------------------------------------------- #
# Entry point
# --------------------------------------------------------------------------- #


def parse_cron(expression: str) -> "CronSchedule":
    """Parse a 5-field cron expression into a :class:`CronSchedule`.

    Raises :class:`CronParseError` if the expression is malformed.
    """
    raw_fields = split_into_fields(expression)
    minutes, hours, days_of_month, months, days_of_week = (
        parse_field(text, field) for text, field in zip(raw_fields, CRON_FIELDS)
    )
    return CronSchedule(
        expression=expression.strip(),
        minutes=minutes,
        hours=hours,
        days_of_month=days_of_month,
        months=months,
        days_of_week=days_of_week,
    )


def split_into_fields(expression: str) -> list[str]:
    """Split an expression on whitespace and verify it has exactly five fields."""
    if not isinstance(expression, str):
        raise CronParseError(
            f"Expected a string expression, got {type(expression).__name__}"
        )

    fields = expression.split()
    if len(fields) != len(CRON_FIELDS):
        expected = ", ".join(field.name for field in CRON_FIELDS)
        raise CronParseError(
            f"Expected {len(CRON_FIELDS)} fields ({expected}), "
            f"got {len(fields)} in {expression.strip()!r}"
        )
    return fields


# --------------------------------------------------------------------------- #
# Field parsing
#
# One shared code path handles all five fields. The grammar:
#
#     field := term ("," term)*
#     term  := base ("/" step)?
#     base  := "*" | number | number "-" number
#
# --------------------------------------------------------------------------- #


def parse_field(text: str, field: CronField) -> tuple[int, ...]:
    """Parse one whole field into the sorted, de-duplicated values it matches."""
    values: set[int] = set()
    for term in text.split(","):
        values.update(parse_term(term, field))
    return tuple(sorted(values))


def parse_term(term: str, field: CronField) -> list[int]:
    """Parse a single comma-separated term, e.g. ``*``, ``5``, ``1-30/5``."""
    base_text, step = split_step(term, field)
    covered = parse_base(base_text, field, open_ended=step > 1)
    return covered[::step]


def split_step(term: str, field: CronField) -> tuple[str, int]:
    """Split ``base/step`` into its parts; a term without ``/`` has a step of 1."""
    if "/" not in term:
        return term, 1

    base_text, _, step_text = term.partition("/")
    step = parse_number(step_text, field, role="step")
    if step < 1:
        raise CronParseError(
            f"Step must be at least 1 in {field.name} term {term!r}, got {step}"
        )
    return base_text, step


def parse_base(base_text: str, field: CronField, open_ended: bool = False) -> list[int]:
    """Parse the pre-step portion of a term into the values it covers.

    ``open_ended`` marks a base that a step will be applied to. In that case a
    bare number is read as "from here to the end of the field", so ``5/15`` in
    the minute field means 5, 20, 35, and 50 rather than just 5.
    """
    if base_text == "*":
        return list(field.full_range())
    if "-" in base_text:
        return parse_range(base_text, field)

    start = parse_value(base_text, field)
    return list(range(start, field.max_value + 1)) if open_ended else [start]


def parse_range(base_text: str, field: CronField) -> list[int]:
    """Parse ``start-end`` into the inclusive list of values between them."""
    start_text, _, end_text = base_text.partition("-")
    start = parse_value(start_text, field)
    end = parse_value(end_text, field)
    if start > end:
        raise CronParseError(
            f"Range start must not exceed end in {field.name} range "
            f"{base_text!r} ({start} > {end})"
        )
    return list(range(start, end + 1))


def parse_value(text: str, field: CronField) -> int:
    """Parse a single number and confirm it falls inside the field's range."""
    value = parse_number(text, field, role="value")
    if not field.contains(value):
        raise CronParseError(
            f"Value {value} is out of range for {field.name} "
            f"(expected {field.min_value}-{field.max_value})"
        )
    return value


def parse_number(text: str, field: CronField, role: str) -> int:
    """Convert text to an int, with an error message naming the field and role."""
    stripped = text.strip()
    if not stripped.isdigit():
        raise CronParseError(
            f"Expected a non-negative integer {role} for {field.name}, got {text!r}"
        )
    return int(stripped)


# --------------------------------------------------------------------------- #
# The parsed result
# --------------------------------------------------------------------------- #


@dataclass(frozen=True)
class CronSchedule:
    """The set of values each cron field matches, plus an English description."""

    expression: str
    minutes: tuple[int, ...]
    hours: tuple[int, ...]
    days_of_month: tuple[int, ...]
    months: tuple[int, ...]
    days_of_week: tuple[int, ...]

    # -- queries ----------------------------------------------------------- #

    def matches_every_minute(self) -> bool:
        return self._covers_all(self.minutes, MINUTE)

    def matches_every_hour(self) -> bool:
        return self._covers_all(self.hours, HOUR)

    def matches_every_day_of_month(self) -> bool:
        return self._covers_all(self.days_of_month, DAY_OF_MONTH)

    def matches_every_month(self) -> bool:
        return self._covers_all(self.months, MONTH)

    def matches_every_day_of_week(self) -> bool:
        return self._covers_all(self.days_of_week, DAY_OF_WEEK)

    @staticmethod
    def _covers_all(values: Sequence[int], field: CronField) -> bool:
        return tuple(values) == tuple(field.full_range())

    # -- description ------------------------------------------------------- #

    def describe(self) -> str:
        """Return a human-readable English description of this schedule.

        The description is one time clause followed by zero or more date
        clauses, e.g. "At 08:30" + "on Monday, Wednesday, and Friday".
        """
        clauses = [self._describe_time(), *self._describe_dates()]
        return " ".join(clause for clause in clauses if clause)

    def _describe_time(self) -> str:
        """Describe the minute and hour fields as a single leading clause."""
        if self.matches_every_minute() and self.matches_every_hour():
            return "Every minute"
        if self.matches_every_hour():
            return self._describe_minutes_of_every_hour()
        if self.matches_every_minute():
            return self._describe_every_minute_of_hours()
        return self._describe_times_of_day()

    def _describe_minutes_of_every_hour(self) -> str:
        """e.g. ``*/15 * * * *`` -> 'Every 15 minutes'."""
        interval = uniform_interval(self.minutes, MINUTE)
        if interval is not None and self.minutes[0] == MINUTE.min_value:
            return f"Every {interval} minutes"
        offsets = [f"{minute:02d}" for minute in self.minutes]
        return f"At {join_list(offsets)} past every hour"

    def _describe_every_minute_of_hours(self) -> str:
        """e.g. ``* 9 * * *`` -> 'Every minute of 09:00-09:59'."""
        spans = [f"{hour:02d}:00-{hour:02d}:59" for hour in self.hours]
        return f"Every minute of {join_list(spans)}"

    def _describe_times_of_day(self) -> str:
        """e.g. ``0 */2 * * *`` -> 'Every 2 hours, on the hour'."""
        interval = uniform_interval(self.hours, HOUR)
        starts_on_the_hour = self.minutes == (0,)
        if (
            interval is not None
            and starts_on_the_hour
            and self.hours[0] == HOUR.min_value
        ):
            return f"Every {interval} hours, on the hour"
        return f"At {join_list(self._clock_times())}"

    def _clock_times(self) -> list[str]:
        """Every hour/minute combination this schedule fires at, as ``HH:MM``."""
        return [
            format_clock_time(hour, minute)
            for hour in self.hours
            for minute in self.minutes
        ]

    def _describe_dates(self) -> list[str]:
        """Describe the day-of-month, month, and day-of-week fields."""
        clauses: list[str] = []

        # Day-of-month and month combine into one phrase so that the result
        # reads "on the 1st of January" rather than "on the 1st" + "January".
        days = self._describe_days_of_month()
        months = self._describe_months()
        if days and months:
            clauses.append(f"{days} of {months}")
        elif days:
            clauses.append(f"{days} of every month")
        elif months:
            clauses.append(f"in {months}")

        if not self.matches_every_day_of_week():
            weekdays = describe_named_values(
                self.days_of_week, WEEKDAY_NAMES, DAY_OF_WEEK
            )
            clauses.append(f"on {weekdays}")

        return clauses

    def _describe_days_of_month(self) -> str:
        """e.g. 'on the 1st and 15th'; empty when the field is a wildcard."""
        if self.matches_every_day_of_month():
            return ""
        return f"on the {join_list([ordinal(day) for day in self.days_of_month])}"

    def _describe_months(self) -> str:
        """e.g. 'March through May'; empty when the field is a wildcard."""
        if self.matches_every_month():
            return ""
        return describe_named_values(self.months, MONTH_NAMES, MONTH)

    def __str__(self) -> str:
        return f"{self.expression}: {self.describe()}"


# --------------------------------------------------------------------------- #
# Formatting helpers
# --------------------------------------------------------------------------- #


def uniform_interval(values: Sequence[int], field: CronField) -> int | None:
    """Return the common gap if ``values`` is an evenly spaced step series.

    Returns ``None`` when the values are irregular, when there are too few of
    them to read as a repeating interval, or when the series stops early and so
    does not actually repeat across the whole field.
    """
    if len(values) < 2:
        return None

    gaps = {later - earlier for earlier, later in zip(values, values[1:])}
    if len(gaps) != 1:
        return None

    interval = gaps.pop()
    spans_whole_field = tuple(range(values[0], field.max_value + 1, interval))
    return interval if spans_whole_field == tuple(values) else None


def format_clock_time(hour: int, minute: int) -> str:
    """Render an hour/minute pair as ``HH:MM``, naming midnight specially."""
    if (hour, minute) == (0, 0):
        return "midnight"
    return f"{hour:02d}:{minute:02d}"


def describe_named_values(
    values: Sequence[int], names: Sequence[str], field: CronField
) -> str:
    """Name each value, collapsing a contiguous run into 'X through Y'.

    ``names`` is indexed from ``field.min_value`` — so weekday 0 is the first
    name, while month 1 is the first name.
    """
    labels = [names[value - field.min_value] for value in values]
    if len(labels) > 2 and is_contiguous(values):
        return f"{labels[0]} through {labels[-1]}"
    return join_list(labels)


def is_contiguous(values: Sequence[int]) -> bool:
    """True when the sorted values form an unbroken run of consecutive ints."""
    return len(values) > 1 and tuple(values) == tuple(range(values[0], values[-1] + 1))


def ordinal(number: int) -> str:
    """Render an integer as an English ordinal: 1 -> '1st', 22 -> '22nd'."""
    if 10 <= number % 100 <= 20:
        suffix = "th"
    else:
        suffix = {1: "st", 2: "nd", 3: "rd"}.get(number % 10, "th")
    return f"{number}{suffix}"


def join_list(items: Sequence[str]) -> str:
    """Join with commas and a serial 'and': ['a', 'b', 'c'] -> 'a, b, and c'."""
    if not items:
        return ""
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} and {items[1]}"
    return f"{', '.join(items[:-1])}, and {items[-1]}"


# --------------------------------------------------------------------------- #
# Demo
# --------------------------------------------------------------------------- #

if __name__ == "__main__":
    EXAMPLES = [
        "* * * * *",
        "0 12 * * 1-5",
        "*/15 * * * *",
        "0 0 1 * *",
        "30 8 * * 1,3,5",
        "0 */2 * * *",
        "0 9 * * 0",
        "15,45 * * * *",
        "0 0 1 1 *",
        "5 4 * 12 *",
        "0 12 1-15/5 * *",
        "* 9 * * *",
    ]
    for example in EXAMPLES:
        print(f"{example:<16} -> {parse_cron(example).describe()}")
```

Expected output of the demo:

```
* * * * *        -> Every minute
0 12 * * 1-5     -> At 12:00 on Monday through Friday
*/15 * * * *     -> Every 15 minutes
0 0 1 * *        -> At midnight on the 1st of every month
30 8 * * 1,3,5   -> At 08:30 on Monday, Wednesday, and Friday
0 */2 * * *      -> Every 2 hours, on the hour
0 9 * * 0        -> At 09:00 on Sunday
15,45 * * * *    -> At 15 and 45 past every hour
0 0 1 1 *        -> At midnight on the 1st of January
5 4 * 12 *       -> At 04:05 in December
0 12 1-15/5 * *  -> At 12:00 on the 1st, 6th, and 11th of every month
* 9 * * *        -> Every minute of 09:00-09:59
```

**Design notes**

- **One shared field parser.** `parse_field` → `parse_term` → `split_step` → `parse_base` → `parse_range` → `parse_value` → `parse_number`. All five fields go through the same chain; the only thing that varies is the `CronField` metadata passed alongside. Each function is a single grammar production, so the code mirrors the grammar comment above it.
- **`CronField` carries the per-field variation** (name, min, max) instead of scattering `if field == "minute"` checks. It also gives error messages the field name for free: `"Value 65 is out of range for minute (expected 0-59)"`.
- **Parsing and describing are fully separate layers.** `CronSchedule` holds only resolved integer tuples — it never sees the original syntax — so `describe()` works off *what the schedule means*, not how it was written. That's why `*/15` and `0,15,30,45` describe identically.
- **`describe()` is a dispatch, not a decision tree.** It picks one time clause from four named cases and appends date clauses; each case is a two-line method whose docstring shows an example. Adding a new phrasing means adding a branch and a method, not editing a nest.
- **Formatting helpers are pure functions** at the bottom (`ordinal`, `join_list`, `uniform_interval`, …), independently testable and reused across weekdays and months via `describe_named_values`.
- **Validation is exhaustive and localized:** wrong field count, non-numeric tokens, out-of-range values, inverted ranges, and zero steps each raise `CronParseError` (a `ValueError` subclass) from the single function responsible for that rule.

One extension beyond the spec worth flagging: `5/15` (bare number with a step) is read as "from 5 to the field maximum, every 15" — the standard cron behavior — via the explicit `open_ended` flag on `parse_base`.

