def _describe_exact_time(hour: int, minute: int) -> str:
    """Format an exact time of day."""
    if hour == 0 and minute == 0:
        return "At midnight"

    return f"At {hour:02d}:{minute:02d}"


def _describe_minute_within_hour(minute: int) -> str:
    """Describe where a minute falls within each selected hour."""
    if minute == 0:
        return "on the hour"

    return f"at {minute} minutes past the hour"


def _describe_calendar(schedule: CronSchedule) -> str:
    """Describe the day and month portions of a schedule."""
    day_of_month = schedule.day_of_month
    day_of_week = schedule.day_of_week
    month = schedule.month

    has_month_days = not day_of_month.is_any
    has_weekdays = not day_of_week.is_any
    has_months = not month.is_any

    month_days = _describe_day_of_month(day_of_month)
    weekdays = _describe_named_field(
        day_of_week,
        lambda value: WEEKDAY_NAMES[value],
    )
    months = _describe_named_field(
        month,
        lambda value: MONTH_NAMES[value - 1],
    )

    if has_month_days and has_weekdays:
        day_clause = f"on {month_days} of the month or on {weekdays}"
        if has_months:
            return f"{day_clause}, in {months}"
        return day_clause

    if has_month_days:
        if has_months:
            return f"on {month_days} in {months}"
        return f"on {month_days} of every month"

    if has_weekdays:
        if has_months:
            return f"on {weekdays} in {months}"
        return f"on {weekdays}"

    if has_months:
        return f"in {months}"

    return ""


def _describe_day_of_month(field: CronField) -> str:
    """Describe selected days using ordinal numbers."""
    return _describe_named_field(
        field,
        lambda value: f"the {_ordinal(value)}",
    )


def _describe_numeric_field(field: CronField) -> str:
    """Describe a numeric field while preserving simple ranges."""
    return _describe_named_field(field, str)


def _describe_named_field(
    field: CronField,
    format_value: Callable[[int], str],
) -> str:
    """Describe selections using a supplied value formatter."""
    phrases = [
        _describe_selection(selection, format_value)
        for selection in field.selections
    ]
    return _join_english(phrases)


def _describe_selection(
    selection: FieldSelection,
    format_value: Callable[[int], str],
) -> str:
    """Describe one parsed selection."""
    if selection.step == 1:
        if selection.start == selection.end:
            return format_value(selection.start)

        return (
            f"{format_value(selection.start)} through "
            f"{format_value(selection.end)}"
        )

    # Expanding stepped selections keeps descriptions unambiguous.
    values = [format_value(value) for value in selection.values()]
    return _join_english(values)


def _join_english(items: list[str]) -> str:
    """Join words using natural English punctuation."""
    if not items:
        return ""

    if len(items) == 1:
        return items[0]

    if len(items) == 2:
        return f"{items[0]} and {items[1]}"

    return f"{', '.join(items[:-1])}, and {items[-1]}"


def _ordinal(value: int) -> str:
    """Convert an integer to an English ordinal such as '1st'."""
    if 10 <= value % 100 <= 20:
        suffix = "th"
    else:
        suffix = {
            1: "st",
            2: "nd",
            3: "rd",
        }.get(value % 10, "th")

    return f"{value}{suffix}"
```

Example usage:

```python
schedule = parse_cron("30 8 * * 1,3,5")

print(schedule.minute.values)  # (30,)
print(schedule.describe())
# At 08:30 on Monday, Wednesday, and Friday
```
